-- Generated by scripts/build_compiled.py from src/fraudrules/rules/first-party/fp-001-sleeper-line-maxout.yaml. Do not edit.
-- FP-001 Seasoned card account draws most of its credit line within a week
SELECT
  'FP-001' AS rule_id,
  'transactions' AS anchor_table,
  a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b
  ON b.account_id = a.account_id AND b.ts <= a.ts AND b.ts > a.ts - 604800
WHERE
  (
    a.account_type = 'card'
    AND a.direction = 'out'
    AND a.txn_type IN ('purchase', 'cash_advance')
    AND a.ts >= (
      a.account_opened_ts + 15552000
    )
    AND a.credit_limit_cents > 0
  )
  AND (
    b.account_type = 'card'
    AND b.direction = 'out'
    AND b.txn_type IN ('purchase', 'cash_advance')
  )
GROUP BY
  a.id
HAVING
  SUM(b.amount_cents) * 100 >= MAX(a.credit_limit_cents) * 90;
